import fs from 'node:fs';
import path from 'node:path';
const read = (p) => fs.readFileSync(p, 'utf8');
const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => {
  const p = path.join(d, e.name);
  return e.isDirectory() ? walk(p) : [p];
});
const defaults = Number(read('src/config.js').match(/attempts:\s*(\d+)/)[1]);
const files = walk('src').filter((f) => /\.(js|ts)$/.test(f));
const callers = [];
const overrides = {};
for (const f of files) {
  if (f === path.join('src', 'net', 'retry.js')) continue;
  const src = read(f);
  const code = src.replace(/\/\/[^\n]*/g, '').replace(/\/\*[\s\S]*?\*\//g, '');
  if (!/(?<!Sync)\bretryWithBackoff\s*\(/.test(code)) continue;
  callers.push(f.split(path.sep).join('/'));
  const m = code.match(/attempts:\s*(\d+)/);
  if (m) overrides[f.split(path.sep).join('/')] = Number(m[1]);
